import json
from collections import defaultdict

THRESHOLD = 5


def parse_logs(log_file):
    failure_count = defaultdict(int)

    with open(log_file, "r", encoding="utf-8") as f:
        for line in f:
            try:
                log = json.loads(line)
            except Exception:
                continue

            if log.get("event_type") == "AUTH_FAILURE":
                device_id = log.get("device_id", "unknown")
                failure_count[device_id] += 1

    for device_id, count in failure_count.items():
        print(f"Device: {device_id} -> AUTH_FAILUREs: {count}")
        if count > THRESHOLD:
            print(f"ALERT: Possible brute force attack on {device_id}")


# Example usage
# parse_logs("logs.jsonl")

def privacy_check(config):
    issues = []

    sensitive_fields = {"location", "video", "audio"}

    collected = set(config.get("collected_data", []))
    missing_sensitive = collected.intersection(sensitive_fields)

    if missing_sensitive:
        issues.append(f"Sensitive data collected: {missing_sensitive}")

    if "retention_days" not in config:
        issues.append("Missing retention period")

    if not config.get("access_control_defined", False):
        issues.append("Missing access control statement")

    if not issues:
        print("Privacy check passed")
    else:
        print("Privacy issues detected:")
        for i in issues:
            print("-", i)


